  str_n5_mission_title_12 = "ST4—Turning the Tide",
  str_n5_mission_title_13 = "N9—Defensive Line",
  str_n5_mission_title_14 = "N10—A Formidable Foe",
  str_n5_mission_title_15 = "N11—Head-on",
  str_n5_mission_title_16 = "ST5—Hope",
  str_n5_mission_desc_1 = "Saat di dalam Colossus, kamu tiba-tiba menerima pesan dari Illumina Undercity.",
  str_n5_mission_desc_2 = "Kamu tiba di Undercity 24 dan bertemu dengan Officer di sana.",
  str_n5_mission_desc_3 = "Sebagai anggota baru gugus tugasnya, Officer Brent tampak sangat khawatir dengan performamu.",
  str_n5_mission_desc_4 = "Kamu bergabung dengan konvoi tanpa hambatan. Akan tetapi, sebelum kamu memulai misi, Brent memberitahumu bahwa kesetiakawanan sangat penting untuk membangun kerja sama dengan tim mana pun.",
  str_n5_mission_desc_5 = "Di antara badai debu dan Eclipsite, sepertinya konvoi tidak mampu melanjutkan misi pengangkutannya. Namun, Ansia menolak menyerah semudah itu.",
  str_n5_mission_desc_6 = "Tentara Eclipsite mendekat, tetapi tidak ada pasukan yang berjaga dan mampu melindungi Undercity 24...",
  str_n5_mission_desc_7 = "Saat Eclipsite raksasa yang terbang itu menyerang, menembaknya jatuh sepertinya opsi tindakan terbaik!",
  str_n5_mission_desc_8 = "Saat dihadapkan pada Eclipsite yang paling kuat, selalu ada orang yang berjuang dengan nyali yang tak tertandingi.",
  str_n5_mission_desc_9 = "Di medan tempur yang kejam, garis antara kemenangan dan kekalahan sangatlah tipis.",
  str_n5_mission_desc_10 = "Setelah mewarisi wasiat perlawanan, sekarang kamu harus menghadapi musuh terbesarmu sekali lagi...",
  str_n5_mission_desc_11 = "Serangan balik belum berakhir. Sekarang kamu harus membawa kabar kemenanganmu kepada kawan-kawan seperjuangan!",
  str_n5_mission_desc_12 = "Pertahanan Undercity 24 hanya satu bagian dari pertempuran ini. Sekarang kamu harus menetapkan target lain.",
  str_n5_mission_desc_13 = "Undercity 23 di baris pertahanan terus menerima serangan dari tentara Eclipsite. Bagaimana kedatanganmu akan mengubah situasi ini?",
  str_n5_mission_desc_14 = "Setelah Barton muncul bersama pasukannya, kamu berhasil merebut kembali bagian belakang. Namun, apakah semuanya akan berjalan selancar itu?",
  str_n5_mission_desc_15 = "Tidak satu pun di antara kalian berniat mundur saat menghadapi musuh yang kuat sekali lagi. Pertempuran ini bukan sekadar langkah menuju kemenangan pemungkas, tetapi juga harus dimenangkan demi menghormati para pahlawan yang telah gugur mendahului kalian!",
  str_n5_mission_desc_16 = "Kembali di Undercity 24, semua orang memutuskan masa depan seperti apa yang ingin mereka perjuangkan.",
  str_n5_mission_desc_long_1 = "Kamu mengalami masalah teknis saat berusaha menghubungi Illumina. Setelah mengotak-atik perangkat komunikasi itu, kamu tiba-tiba menerima pesan dari Undercity 24, yang meminta bantuan. Percaya dengan penjelasan Vice, kamu akhirnya memutuskan untuk pergi ke Undercity 24.",
  str_n5_mission_desc_long_2 = "Kamu mendarat di Transport Station, dan di sanalah kamu bertemu dengan Officer Brent. Setelah mendengar niatmu, Officer yang memimpin gugus tugas Undercity 24 itu memutuskan untuk langsung memasukkanmu ke pasukannya.",
  str_n5_mission_desc_long_3 = "Tidak yakin dengan kebugaran fisik dan keterampilan komandomu, Officer Brent memintamu langsung menunjukkan caramu bertarung melawan Eclipsite. Saat kamu terancam kewalahan dikeroyok Eclipsite, seorang prajurit bernama Gram muncul.",
  str_n5_mission_desc_long_4 = "Ansia, salah satu kawan dalam konvoi, meminta bantuanmu untuk melerai pertengkaran dua anggota lain. Setelah mendengarkan cerita mereka, kamu menyadari bahwa penyebabnya adalah Ansia sendiri.",
  str_n5_mission_desc_long_5 = "Ansia, pemimpin konvoi, meminta dengan sungguh-sungguh agar kamu menggunakan Colossus untuk mengangkut barang-barang itu ke Undercity 23. Selama waktu persiapanmu yang singkat, kamu menyadari bahwa bakat rahasia Gram adalah memasak.",
  str_n5_mission_desc_long_6 = "Brent tetap tenang dalam menghadapi bahaya saat melawan tentara Eclipsite. Dia memerintahkan agar Colossus digunakan untuk mengevakuasi sebagian warga sipil dan agar pasukan yang ada di kota dibagi menjadi dua unit. Satu unit bertugas menyerang boss Eclipsite, sementara yang lain membantu upaya bombardir sebagai perlawanan terhadap serangan Eclipsite di kota.",
  str_n5_mission_desc_long_7 = "Officer veteran Undercity 24 berhasil menembak jatuh boss Eclipsite. Kamu pergi ke tempat kejatuhannya, sesuai rencana, dan bersiap menghabisinya. Namun, satu-satunya hal pasti di medan tempur adalah ketidakpastian, dan ledakan yang mengguncang tanah.",
  str_n5_mission_desc_long_8 = "Saat sang Eclipsite raksasa menyerang Undercity 24, Brent dengan cepat menyusun rencana tempur dan memutuskan membawa skuad kecil untuk menghadapinya. Pada akhirnya, mereka menggunakan jebakan darat dan ranjau di stasiun untuk mengalahkan Eclipsite yang tangguh itu.",
  str_n5_mission_desc_long_9 = "Setelah beruntung bisa selamat dari ledakan, kamu bergegas kembali ke stasiun. Akan tetapi, boss Eclipsite yang jatuh itu, yang dikira sudah tewas terkena ledakan, bangun kembali dan menyerang Brent...",
  str_n5_mission_desc_long_10 = "Brent terkena serangan langsung dari musuh Eclipsite, tetapi semangatnya tetap berkobar meski dalam keadaan sekarat. Melihat kedatanganmu yang cepat, dia percaya kamu bisa mengalahkan Eclipsite itu dan melindungi Undercity.",
  str_n5_mission_desc_long_11 = "Dengan kegigihanmu yang luar biasa, Undercity 24 berhasil diamankan. Gram memutuskan untuk mengabarkan berita kemenanganmu kepada saudara seperjuangannya di masa lalu, dan mengucapkan selamat tinggal kepadanya.",
  str_n5_mission_desc_long_12 = "Setelah menyimpulkan bahwa target Eclipsite sebenarnya adalah kargo yang diangkut oleh konvoi, kamu memutuskan untuk mendampingi angkutan penting ini ke tujuan akhirnya—Undercity 23 di Dunefire Line, ke baris pertahanan pertama terhadap serangan Eclipsite.",
  str_n5_mission_desc_long_13 = "Setelah menggunakan Colossus dan kemampuan psikismu untuk memastikan situasi di sepanjang baris pertahanan, Gram, yang memiliki pengalaman tempur bertahun-tahun, memutuskan untuk melancarkan serbuan pada Eclipsite untuk menyudahi pengepungan Undercity 23. Maka, kamu memutuskan... untuk terjun langsung dari Colossus ke area musuh!",
  str_n5_mission_desc_long_14 = "Walau situasi sepertinya sudah berbalik, awan gelap berkumpul kembali ketika bos Eclipsite muncul sekali lagi.",
  str_n5_mission_desc_long_15 = "Semua siap bertempur menghadapi musuh yang tangguh ini lagi. Terbakar amarah dan semangat pantang menyerah, kamu menyingkirkan musuhmu, meraih kemenangan dalam mempertahankan Undercity 23, dan keberhasilan terakhirmu dalam menjaga baris pertahanan.",
  str_n5_mission_desc_long_16 = "Setelah Dunefire Vanguard mendeklarasikan kemenangan mutlaknya dalam mempertahankan diri, kamu kembali ke Undercity24. Di tengah kesunyian euforia pasca-pertempuran, semua orang memutuskan jalan masing-masing yang ingin mereka ambil di masa mendatang—hidup demi cita-cita mereka dan bertempur berdampingan, dengan dan demi kompatriot mereka.",
  str_n5_battlefield_refreshed = "Reset Pertempuran",
  str_n5_record_militaryexploit = "Merit yang diperoleh akan direkam.",
  str_n5_today_max_militaryexploit = "Dari empat medan tempur berikut, hanya medan tempur di mana kamu memperoleh Merit tertinggi dalam seharilah yang akan ditambahkan ke Total Merit."
}
